<script lang="ts">
  import { t } from '#lib/i18n/index.ts';
  import { getAlertTitle, getAlertMessage } from '#lib/utils/alert-copy.ts';
  import Panel from './Panel.svelte'; import Meter from './Meter.svelte';
  import Icon from '#lib/components/Icon.svelte'; import BarChart from '#lib/components/BarChart.svelte'; import LineChart from '#lib/components/LineChart.svelte';
  import { evaluateAlerts } from '#lib/api/alerts.ts';
  import { applyRules } from '#lib/api/rules.ts';
  import { apiPut, apiPatch, apiDelete } from '#lib/api/client.ts';
  import { number as n, text, rows, object, type Model, type Actions, type Row } from './model';
  let { m, a }: { m: Model; a: Actions } = $props();
  let alertType=$state(''); let evaluating=$state(false);
  const alertTypes=['balance_low','credit_high','payment_due','payment_overdue','budget_threshold','budget_exceeded','goal_completed'];
  async function evaluate(){evaluating=true;error='';try{await evaluateAlerts();await a.refresh();a.notify(m.t('cyberpunk.alerts_evaluated'));}catch(e){error=e instanceof Error?e.message:String(e);}finally{evaluating=false;}}
  let categoryType=$state(''); let severity=$state(''); let readFilter=$state(''); let expanded=$state(0); let error=$state('');
  const monthly=$derived(object(m.dashboard.monthlySummary));
  const breakdown=$derived(rows(m.dashboard.categoryBreakdown));
  const activeAlerts=$derived(m.alerts.filter(row=>!row.isRead));
  const visibleAlerts=$derived(m.alerts.filter(row=>(!alertType||row.type===alertType)&&(!severity||text(row.severity).toLowerCase()===severity)&&(!readFilter||Boolean(row.isRead)===(readFilter==='read'))));
  async function apply(){try{const result=await applyRules();a.notify(`${result.matched} / ${result.processed}`);await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
  async function toggle(row:Row) {try{error='';await apiPut(`/rules/${row.id}`,{enabled:!row.enabled});await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
  async function read(id?:number) {try{error='';await apiPatch(id?`/alerts/${id}/read`:'/alerts/read-all');await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
  async function remove(id:number) {try{error='';await apiDelete(`/alerts/${id}`);await a.refresh();}catch(e){error=e instanceof Error?e.message:String(e);}}
</script>
{#if error}<p class="cp-error" role="alert">{error}</p>{/if}
{#if m.route === 'categorias'}
  <div class="cp-toolbar"><div class="cp-tabs">{#each [['',m.t('cyberpunk.overview')],['Ingreso',m.t('search.type_income')],['Gasto',m.t('dashboard.expenses')]] as [value,label]}<button class:active={categoryType===value} onclick={()=>categoryType=value}>{label}</button>{/each}</div><button class="cp-button" onclick={()=>a.edit('categories')}>+ {m.t('cyberpunk.new_category')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.t('cyberpunk.monthly_income')}</span><strong class="cp-cyan">{m.money(monthly.totalIncome)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.monthly_expenses')}</span><strong class="cp-red">{m.money(monthly.totalExpenses)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.monthly_savings')}</span><strong class="cp-yellow">{m.money(n(monthly.totalIncome)-n(monthly.totalExpenses))}</strong></div></div>
  {#each [['Ingreso',m.t('cyberpunk.income_categories')],['Gasto',m.t('cyberpunk.expense_categories')]] as [type,title]}{#if !categoryType||categoryType===type}<Panel {title}><div class="cp-category-grid">{#each m.categories.filter(row=>row.type===type||row.type==='Ambos') as row}<article class="cp-category-tile"><button class="cp-text-button" onclick={()=>a.edit('categories',row)}><Icon name={text(row.icon)||'tag'} size={32}/><strong>{text(row.name)}</strong></button>{#if type==='Gasto'}{@const amount=breakdown.find(c=>n(c.categoryId)===row.id)}<b class="cp-number">{m.money(amount?.total)}</b><Meter value={n(amount?.percentage)} label={text(row.name)} tone="red"/>{:else}<span class="cp-muted">{rows(row.subcategories).length} {m.t('cyberpunk.subcategories')}</span>{/if}<div class="cp-subcategories">{#each rows(row.subcategories) as sub}<span>{text(sub.name)}</span>{/each}</div><button class="cp-link" onclick={()=>a.edit('categories',row)}>+ {m.t('categories.subcategories')}</button></article>{:else}<p class="cp-empty">{m.t('cyberpunk.no_categories_yet')}</p>{/each}<button class="cp-add-tile" onclick={()=>a.edit('categories',{id:0,type})}><Icon name="plus" size={28}/>{m.t('cyberpunk.add_category')}</button></div></Panel>{/if}{/each}
{:else if m.route === 'reglas'}
  <div class="cp-toolbar"><div class="cp-stats plain"><div class="cp-stat"><span>{m.t('cyberpunk.active_rules')}</span><strong class="cp-cyan">{m.rules.filter(row=>row.enabled).length}</strong><small>{m.rules.length} {m.t('cyberpunk.total')}</small></div><div class="cp-stat"><span>{m.t('cyberpunk.automatic_categorization')}</span><strong class="cp-yellow">{m.t('cyberpunk.rules_engine')}</strong></div></div><button class="cp-button" onclick={apply}>{m.t('cyberpunk.apply_rules')}</button><button class="cp-button" onclick={()=>a.edit('rules')}>+ {m.t('rules.new')}</button></div>
  <Panel title={m.t('cyberpunk.categorization_rules')}><div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('settings.totp_on')}</th><th>{m.t('rules.col_priority')}</th><th>{m.t('cyberpunk.name_condition')}</th><th>{m.t('cyberpunk.action')}</th><th></th></tr></thead><tbody>{#each m.rules as row}<tr><td><button class="cp-switch" class:on={Boolean(row.enabled)} role="switch" aria-checked={Boolean(row.enabled)} aria-label={text(row.name)} onclick={()=>toggle(row)}><span></span></button></td><td class="cp-number">{n(row.priority)}</td><td><b>{text(row.name)}</b>{#each rows(row.conditions) as condition}<small class="cp-condition">{text(condition.field)} {text(condition.operator)} “{text(condition.value)}”</small>{/each}</td><td>{#each rows(row.actions) as action}<span class="cp-rule-action">{action.type==='setCategory'?`${m.t('search.filter_category')}: ${m.category(action.value)}`:`${text(action.type)} ${text(action.value)}`}</span>{/each}</td><td><button class="cp-button ghost small" onclick={()=>a.edit('rules',row)}>{m.t('rules.edit_title')} →</button><button class="cp-link cp-red" onclick={()=>a.edit('rule-delete',row)}>{m.t('receipts.delete')}</button></td></tr>{:else}<tr><td class="cp-empty" colspan="5">{m.t('cyberpunk.create_your_first_categorization_rule')}</td></tr>{/each}</tbody></table></div></Panel>
{:else if m.route === 'reportes'}
  <div class="cp-tabs"><button class="active">{m.t('cyberpunk.overview')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.t('cyberpunk.monthly_income')}</span><strong class="cp-cyan">{m.money(monthly.totalIncome)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.monthly_expenses')}</span><strong class="cp-red">{m.money(monthly.totalExpenses)}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.net_cash_flow')}</span><strong class="cp-yellow">{m.money(n(monthly.totalIncome)-n(monthly.totalExpenses))}</strong></div></div>
  <div class="cp-two"><Panel title={m.t('cyberpunk.monthly_cash_flow')}><div class="cp-legend"><span class="cp-cyan">■ {m.t('search.type_income')}</span><span class="cp-red">■ {m.t('dashboard.expenses')}</span></div><BarChart labels={m.trends.map(row=>text(row.month))} datasets={[{label:m.t('search.type_income'),data:m.trends.map(row=>n(row.income)),backgroundColor:'#6ff4ed'},{label:m.t('dashboard.expenses'),data:m.trends.map(row=>n(row.expenses)),backgroundColor:'#ff6b76'}]} height={220}/></Panel><Panel title={m.t('cyberpunk.net_cash_flow_trend')}><LineChart labels={m.trends.map(row=>text(row.month))} datasets={[{label:m.t('cyberpunk.net_cash_flow'),data:m.trends.map(row=>n(row.income)-n(row.expenses)),borderColor:'#6ff4ed',fill:true,backgroundColor:'#6ff4ed22'}]} height={250}/></Panel><Panel title={m.t('cyberpunk.spending_by_category')}>{#each breakdown as row}<div class="cp-category-bar"><span>{text(row.categoryName)}</span><Meter value={n(row.percentage)} label={text(row.categoryName)} tone="red"/><strong class="cp-number">{m.money(row.total)}</strong></div>{:else}<p class="cp-empty">{m.t('cyberpunk.no_category_spending_this_month')}</p>{/each}</Panel><Panel title={m.t('cyberpunk.income_vs_expenses')}><table class="cp-table"><thead><tr><th>{m.t('loans.sched_month')}</th><th>{m.t('search.type_income')}</th><th>{m.t('dashboard.expenses')}</th><th>{m.t('reports.savings')}</th></tr></thead><tbody>{#each m.trends as row}<tr><td>{text(row.month)}</td><td class="cp-number cp-cyan">{m.money(row.income)}</td><td class="cp-number cp-red">{m.money(row.expenses)}</td><td class="cp-number cp-yellow">{m.money(n(row.income)-n(row.expenses))}</td></tr>{/each}</tbody></table></Panel></div>
{:else}
  <div class="cp-toolbar"><div class="cp-tabs">{#each [['',m.t('search.entity_all')],['critical',m.t('subscriptions.urgent')],['warning',m.t('cyberpunk.upcoming')],['info',m.t('cyberpunk.information')]] as [value,label]}<button class:active={severity===value} onclick={()=>severity=value}>{label}</button>{/each}</div><select aria-label={m.t('cyberpunk.alert_type')} bind:value={alertType}><option value="">{$t('alerts.filter_type_all')}</option>{#each alertTypes as type}<option value={type}>{$t(`alerts.filter_${type}`)}</option>{/each}</select><button class="cp-button" disabled={evaluating} onclick={evaluate}>{evaluating?'…':$t('alerts.evaluate_now')}</button><button class="cp-button ghost" onclick={()=>read()}>{m.t('alerts.mark_all_read')}</button></div>
  <div class="cp-stats"><div class="cp-stat"><span>{m.t('cyberpunk.need_attention')}</span><strong class="cp-red">{activeAlerts.filter(row=>text(row.severity).toLowerCase()==='critical').length}</strong></div><div class="cp-stat"><span>{m.t('cyberpunk.upcoming')}</span><strong>{activeAlerts.filter(row=>text(row.severity).toLowerCase()==='warning').length}</strong></div><div class="cp-stat"><span>{m.t('alerts.filter_read')}</span><strong class="cp-cyan">{m.alerts.filter(row=>row.isRead).length}</strong></div></div>
  <Panel title={m.t('cyberpunk.notifications')}>{#snippet action()}<select aria-label={m.t('cyberpunk.read_status')} bind:value={readFilter}><option value="">{m.t('cyberpunk.all_notifications')}</option><option value="unread">{m.t('alerts.filter_unread')}</option><option value="read">{m.t('alerts.filter_read')}</option></select>{/snippet}<div class="cp-table-wrap"><table class="cp-table"><thead><tr><th>{m.t('cyberpunk.alert')}</th><th>{m.t('cyberpunk.details')}</th><th>{m.t('receipts.form_date')}</th><th>{m.t('common.status')}</th><th></th></tr></thead><tbody>{#each visibleAlerts as row}<tr><td><Icon name={text(row.severity).toLowerCase()==='info'?'info':'alert-triangle'} size={23}/></td><td><button class="cp-text-button" onclick={()=>expanded=expanded===row.id?0:row.id}><b>{getAlertTitle(row, $t)}</b></button><p class="cp-muted">{getAlertMessage(row, $t)}</p>{#if expanded===row.id}<div class="cp-inline-actions"><button class="cp-link" onclick={()=>read(row.id)}>{m.t('alerts.mark_read')}</button><button class="cp-link cp-red" onclick={()=>remove(row.id)}>{m.t('cyberpunk.delete_alert')}</button></div>{/if}</td><td>{m.date(row.createdAt)}</td><td><span class="cp-badge" class:urgent={text(row.severity).toLowerCase()==='critical'}>{row.isRead?m.t('alerts.filter_read'):m.t('alerts.filter_unread')}</span></td><td><button class="cp-icon-button" aria-label={m.t('cyberpunk.alert_actions')} onclick={()=>expanded=expanded===row.id?0:row.id}>···</button></td></tr>{:else}<tr><td class="cp-empty" colspan="5">{m.t('cyberpunk.you_are_all_caught_up')}</td></tr>{/each}</tbody></table></div></Panel>
{/if}
